package com.learnagent.weekly;import com.learnagent.notification.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.event.ApplicationReadyEvent;import org.springframework.context.event.EventListener;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component@ConditionalOnProperty(prefix="learnagent.weekly-review",name="enabled",havingValue="true")public class WeeklyReviewScheduler{private final WeeklyReviewService service;private final NotificationService notifications;public WeeklyReviewScheduler(WeeklyReviewService service,NotificationService notifications){this.service=service;this.notifications=notifications;}@Scheduled(cron="${learnagent.weekly-review.cron}",zone="${learnagent.time-zone}")public void generateScheduledReview(){generateIfMissing();}@EventListener(ApplicationReadyEvent.class)public void catchUp(){try{generateIfMissing();}catch(RuntimeException ignored){}}private void generateIfMissing(){if(service.existsCurrentWeek())return;var review=service.generate();notifications.create(NotificationType.WEEKLY_REVIEW,"本周学习周报已生成","查看本周进展、薄弱点与下周计划。","/weekly-review","WEEKLY_REVIEW",review.id(),"weekly-"+review.periodStart());}}
